function StoreSkinCell:BtnNodeOnClickHandler()
    if CardSkinComponent:IsHasSkin(self._cellData.goodsId) then
        -- 已拥有
        GameUtils.Toast(localize("皮肤已拥有"))
        return
    end
    
    StoreUtils.OpenChestBuyDialog(self._openId, self._cellData)
end

