--region private
---刷新cell状态
function StoreSkinCell:RefreshCellState(data)
    if CardSkinComponent:IsHasSkin(data.goodsId) then
        -- 已拥有
        KTool.SetActive(self.Price, false)
        KTool.SetActive(self.None, true)
        KTool.SetActive(self.DisableMask, true)
        KTool.SetActive(self.NotGet, false)
        KTool.SetActive(self.ImgSold, checkInt(data.currentStock) == 0)
        KTool.SetActive(self.UIFX_StoreStyle, false)
        return
    end

    local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(data.goodsId)
    if not CardComponent:IsHasCard(skinVo.roleId) then
        -- 卡牌未拥有
        KTool.SetActive(self.Price, true)
        KTool.SetActive(self.None, false)
        KTool.SetActive(self.DisableMask, true)
        KTool.SetActive(self.NotGet, true)
        KTool.SetActive(self.UIFX_StoreStyle, false)
        return
    end

    KTool.SetActive(self.Price, true)
    KTool.SetActive(self.None, false)
    KTool.SetActive(self.DisableMask, false)
    KTool.SetActive(self.NotGet, false)
    KTool.SetActive(self.UIFX_StoreStyle, true)
end

---刷新剩余时间
function StoreSkinCell:RefreshTimeGroup(data)
    KTool.SetActive(self.TimeNode, data.nextRefreshLeftSeconds > 0)
    if data.nextRefreshLeftSeconds > 0 then
        CfUtils.FillText(self.TextDay, StoreUtils.FormatTime(data.nextRefreshLeftSeconds, true))
    end
end

---刷新皮肤
function StoreSkinCell:RefreshSkin(data)
    local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(data.goodsId)
    local skinGoodsVo = CfUtils.GetCfVo(AutoIds.IdSetting711, "SkinGoodsVo", data.goodsId)
    CfUtils.FillImage(self.ImgRole, skinVo.cardDrawing)
    CfUtils.FillText(self.TextName, skinVo.name)
    local switchStatus = SkinQualitySwitchMap[checkInt(skinGoodsVo.quality)]
    CfUtils.SetUISwitchImage(self.ImgQuality, switchStatus)
    CfUtils.SetUISwitchImage(self.UIFX_StoreStyleGlow, switchStatus)
    CfUtils.SetUISwitchParticleSystem(self.UIFX_StoreStyleLiuGuang, switchStatus)
end

---刷新价格
function StoreSkinCell:RefreshPrice(data)
    local currencyVo = GoodsConfMgr:GetInstance():GetGoodsVoById(checkNumber(data.prices[1].currency))
    if data.prices[1].original ~= 0 then
        CfUtils.FillImage(self.CurPriceIcon, currencyVo.photoPath)
        CfUtils.FillText(self.CurPriceText, data.prices[1].current)
        CfUtils.FillImage(self.OriPriceIcon, currencyVo.photoPath)
        CfUtils.FillText(self.OriPriceText, data.prices[1].original)
    else
        CfUtils.FillImage(self.OriPriceIcon, currencyVo.photoPath)
        CfUtils.FillText(self.OriPriceText, data.prices[1].current)
    end

    local tabType = checkInt(data.iconId)
    KTool.SetActive(self.DiscountGroup, false)
    KTool.SetActive(self.ActivityTabelGroup, false)
    if tabType == TagType.Activity then
        KTool.SetActive(self.ActivityTabelGroup, true)
    elseif tabType == TagType.Discount then
        CfUtils.FillText(self.DiscountTxtNumber, data.iconTitle)
        KTool.SetActive(self.DiscountGroup, true)
    end
end
